 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2:
                continue
            candidates = [(h-1-r,c),(r,w-1-c),(h-1-r,w-1-c)]
            vals = [grid[a][b] for a,b in candidates if grid[a][b] != 2]
            if vals:
                # The underlying design is symmetric; all available reflected copies agree.
                out[r][c] = vals[0]
    return out
